function artistPage(slug){const artist=artistList().find(e=>e.artist_slug===slug);if(!artist){app.innerHTML='<h1>Artist not found.</h1><a href="/">Browse artists</a>';return}const shows=upcoming(slug);const demos=state.events.filter(e=>e.artist_slug===slug&&e.source!=='Ticketmaster');app.innerHTML=`<a class="back" href="/artists"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>All artists</a><section class="artist-hero"><div><h1>${esc(artist.artist)}</h1><p class="artist-tour">${artist.source==='Ticketmaster'?(shows.length?esc(artist.tour_label||'Upcoming shows & appearances')+' · '+esc(artistYears(slug)):'No upcoming dates listed in this snapshot'):'Your community starts here.'}</p><a class="button secondary" href="/log?artist=${esc(slug)}">Log a past ${esc(artist.artist)} show</a><p class="intro">${artist.source==='Ticketmaster'?'Find a city. Choose a night. Be part of the crowd.':'Tour dates have not been imported for this artist yet.'}</p>${artist.source==='Ticketmaster'?`<div class="artist-stats"><span><strong>${shows.length}</strong> upcoming shows</span><span><strong>${new Set(shows.map(e=>e.city)).size}</strong> cities</span></div><p class="source-note">Source: <a href="${esc(artist.source_url)}" target="_blank" rel="noopener">Ticketmaster</a> · Imported ${esc(artist.imported_at)}<br>Saved snapshot, not live updates. Confirm changes with the original listing.</p>`:''}</div>${artist.artist_mark?`<figure class="artist-crayon"><img src="${esc(artist.artist_mark)}" alt="" width="200" height="200"></figure>`:`<div class="artist-mark" aria-hidden="true"><span>${esc(artist.artist.split(' ').map(word=>word[0]).slice(0,2).join(''))}</span><div class="orbit"></div><p>SEE YOU<br>IN THE CROWD.</p></div>`}</section><section id="artist-about" class="artist-about" aria-live="polite"><p class="muted">Loading artist details…</p></section>${artist.source==='Ticketmaster'?`<section class="tour-section"><div class="section-head"><div><h2>Find your night.</h2></div><span class="muted">Dates and times local to each venue</span></div><div class="tour-filters"><label>Search city or venue<input id="tour-search" name="tour-search" type="search" autocomplete="off" placeholder="Try Brooklyn, London, Intuit Dome…"></label><label>Show type<select id="tour-kind"><option value="all">All upcoming shows</option><option value="tour">Tour dates</option><option value="appearance">Other appearances</option></select></label></div><p id="tour-count" class="muted" aria-live="polite"></p><div id="tour-list"></div></section>`:''}${demos.length?`<section class="demo-archive"><details><summary>Development-only test ${demos.length===1?'event':'events'} (${demos.length})</summary><p class="muted">Separate unconfirmed placeholders for testing NFC and chat. Not part of the imported schedule.</p><div class="cards">${demos.map(card).join('')}</div></details></section>`:''}`;loadArtistAbout(artist);if(artist.source!=='Ticketmaster')return;function draw(){const query=document.querySelector('#tour-search').value.toLocaleLowerCase().trim(),kind=document.querySelector('#tour-kind').value;const filtered=shows.filter(e=>(kind==='all'||e.kind===kind)&&[e.city,e.venue,e.country,e.region,e.date].join(' ').toLocaleLowerCase().includes(query));document.querySelector('#tour-count').textContent=filtered.length+' upcoming '+(filtered.length===1?'show':'shows')+(query?' matching your search':'');document.querySelector('#tour-list').innerHTML=filtered.length?filtered.map(e=>{const d=e.start_date?new Date(e.start_date+'T12:00:00'):null;return `<article class="tour-row"><div class="date-tile"><span>${d?d.toLocaleDateString(undefined,{month:'short'}):'DATE'}</span><strong>${d?d.getDate():'TBA'}</strong><small>${d?d.getFullYear():''}</small></div><div class="tour-place"><h3>${esc(e.city)}${e.region?', '+esc(e.region):''} <span class="country">${esc(e.country)}</span></h3><p>${esc(e.venue)}</p><small>${d?d.toLocaleDateString(undefined,{weekday:'long'}):'Date to be announced'}${e.local_time?' · '+esc(showTime(e.local_time))+' local time':''}${e.status!=='Scheduled'?' · '+esc(e.status):''}</small>${e.kind==='appearance'?`<p class="appearance-label">Other appearance · ${esc(e.title)}</p>`:''}</div><div class="tour-actions"><a class="button row-action" href="/event/${esc(e.id)}">Open show</a><a class="source-link" href="${esc(e.source_url)}" target="_blank" rel="noopener">Original listing</a></div></article>`}).join(''):!shows.length?'<div class="empty"><h3>No upcoming dates listed.</h3><p>This Ticketmaster snapshot has no upcoming shows for this artist. Check the source for new announcements.</p></div>':'<div class="empty"><h3>No matching shows.</h3><p>Try another city or clear the search.</p></div>'}document.querySelector('#tour-search').oninput=draw;document.querySelector('#tour-kind').onchange=draw;draw()}

function checkinPanelMarkup(e,checked,tap){
 const gps=e.gps_checkin,simulation=tap&&state.demo_checkins_enabled!==false;
 const windowLabel=gps?.opens_at?`<small class="location-window">Check-in window: ${esc(new Date(gps.opens_at).toLocaleString())} – ${esc(new Date(gps.closes_at).toLocaleString())} (your time)</small>`:'';
 return `<div class="check-panel location-checkin"><span class="icon" aria-hidden="true">${checked?'<svg class="icon-star icon-inline" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.6l2.75 5.95 6.5.72-4.86 4.4 1.38 6.4L12 16.8l-5.77 3.27 1.38-6.4-4.86-4.4 6.5-.72z"/></svg>':'◎'}</span><div><strong>${checked?'You’re part of this night.':simulation?'Try the NFC experience.':'At the venue? You’re in.'}</strong><p>${checked?'Your check-in is saved. Enjoy your exclusive crowd.':simulation?'Development preview of the NFC unlock.':'Check in with your location to collect this night and unlock the attendee chat.'}</p><button id="checkin" ${!checked&&!simulation&&!gps?.available?'disabled':''}>${checked?'View my concert history':simulation?'Simulate NFC tap · development only':'◎ Check in with location'}</button><p id="location-checkin-status" class="muted" role="status" aria-live="polite">${checked||simulation?'':esc(gps?.reason||'Location check-in is not set up for this venue yet.')}</p>${checked?'':windowLabel}${checked||simulation?'':'<small>Your location is requested once when you check in. Precise coordinates are not saved. Be within 500 metres of the venue.</small>'}<p class="nfc-future">${simulation?'NFC preview · copied links do not verify attendance.':'NFC taps are also part of Souvenue. Venue tag support is coming.'}</p>${!checked&&!simulation&&state.demo_checkins_enabled!==false?'<details class="demo-checkin-option"><summary>Development tools</summary><button type="button" class="secondary" id="simulate-nfc">Simulate NFC tap</button><small>Prototype only. This bypasses location and showtime checks.</small></details>':''}</div></div>`
}
async function gpsCheckin(e){
 if(checkingIn||attended(e))return;
 const button=document.querySelector('#checkin'),status=document.querySelector('#location-checkin-status'),path=location.pathname;
 const showError=message=>{if(location.pathname===path&&status)status.textContent=message};
 if(globalThis.isSecureContext===false){showError('Location needs a secure connection. Use localhost for laptop testing.');return}
 if(!globalThis.navigator?.geolocation){showError('Location is unavailable in this browser. Try opening Souvenue in your device’s browser.');return}
 checkingIn=true;if(button)button.disabled=true;if(status)status.textContent='Finding your precise location…';
 try{
  const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,maximumAge:0,timeout:20000}));
  if(location.pathname!==path)return;
  if(status)status.textContent='Checking your location at the venue…';
  const award=await api('checkin-gps',{event:e.id,latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy,timestamp:position.timestamp});
  state=await api('state');if(location.pathname!==path)return;tab='chat';render();unlockCelebration(e,award.points_awarded)
 }catch(err){showError(err.code===1?'Location permission was denied. Allow precise location in your browser settings, then try again.':err.code===2?'Your location could not be found. Enable precise location and try outdoors.':err.code===3?'Finding your location took too long. Please try again.':err.message||'Could not check in. Please try again.')}
 finally{checkingIn=false;if(button&&location.pathname===path)button.disabled=false}
}

// Show ticket (TearTicket from React Bits, ported in /tear-ticket.js): artist, venue and date.
// Loads torn if you checked in; a stub you tear stays torn for this visit.
const tornTickets=new Set();let activeTicket=null;
function showTime(t){const m=/^(\d{1,2}):(\d{2})/.exec(t||'');if(!m)return t||'';const h=+m[1];return `${h%12||12}:${m[2]} ${h<12?'AM':'PM'}`}
// Re-save a photo before upload: drops all hidden metadata (GPS location, camera,
// timestamps), applies the phone's rotation, and scales to 2000px so it fits the limit.
const RAW_PHOTO_LIMIT=40000000;
async function cleanPhoto(file){
 let source=null,bitmap=null;
 try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});source=bitmap}catch{source=await new Promise((ok,bad)=>{const img=new Image();img.onload=()=>ok(img);img.onerror=()=>bad(Error('Could not read this photo. Please choose another.'));img.src=URL.createObjectURL(file)})}
 const w=source.width||source.naturalWidth,h=source.height||source.naturalHeight,k=Math.min(1,2000/Math.max(w,h));
 const canvas=document.createElement('canvas');canvas.width=Math.round(w*k);canvas.height=Math.round(h*k);
 const g=canvas.getContext('2d');g.fillStyle='#080b18';g.fillRect(0,0,canvas.width,canvas.height);g.drawImage(source,0,0,canvas.width,canvas.height);bitmap?.close?.();
 const data=canvas.toDataURL('image/jpeg',.86);return {data,size:Math.round((data.length-data.indexOf(',')-1)*3/4)}}
function eventTicketMarkup(e,compact=false){const d=e.start_date?new Date(e.start_date+'T12:00:00'):null,full=d?d.toLocaleDateString(undefined,compact?{weekday:'short',month:'short',day:'numeric',year:'numeric'}:{weekday:'long',month:'long',day:'numeric',year:'numeric'}):e.date,place=[e.city,e.region].filter(Boolean).join(', '),len=e.artist.length,size=compact?(len>20?20:len>14?24:30):(len>20?30:len>14?36:44);
 return {body:`<div class="ticket-body"><strong class="ticket-artist" style="font-size:${size}px">${esc(e.artist)}</strong><span class="ticket-venue">${esc(e.venue)}</span><span class="ticket-city">${esc(place)}</span><span class="ticket-date">${esc(full)}${e.local_time?' · '+esc(showTime(e.local_time)):''}</span></div>`,
  stub:compact?'<div class="ticket-stub"><span class="ticket-stub-only">Admit one</span></div>':`<div class="ticket-stub"><span class="ticket-stub-label">Admit one</span>${d?`<strong class="ticket-stub-day">${d.getDate()}</strong><span class="ticket-stub-month">${d.toLocaleDateString(undefined,{month:'short',year:'numeric'})}</span>`:`<span class="ticket-stub-month">${esc(e.date)}</span>`}<span class="ticket-stub-hint">Pull to tear</span></div>`}}
function mountEventTicket(e,checked){const host=document.querySelector('[data-event-ticket]');if(!host)return;activeTicket?.destroy();activeTicket=null;
 import('/tear-ticket.js').then(({default:mountTearTicket})=>{if(!host.isConnected)return;const narrow=host.clientWidth<480,w=Math.max(300,Math.min(host.clientWidth,480)),{body,stub}=eventTicketMarkup(e,narrow);
  activeTicket=mountTearTicket(host,{body,stub,orientation:'horizontal',width:narrow?w:500,height:narrow?Math.round(w*.6):280,stubSize:narrow?Math.round(w*.28):150,className:narrow?'tear-ticket--compact':'',
   defaultTorn:checked||tornTickets.has(e.id),onTear:()=>tornTickets.add(e.id),rotate:narrow?0:-2,tiltMax:7,parallax:0,
   background:'#1a1e3d',color:'#f2f1ff',borderColor:'#3a3e66',ariaLabel:`Tear the stub off your ${e.artist} ticket`});host.querySelector('.tear-ticket__plane')?.insertAdjacentHTML('afterbegin','<div class="ticket-halo" aria-hidden="true"></div>');const ticket=activeTicket;document.querySelector('.ticket-reset').onclick=()=>{tornTickets.delete(e.id);ticket.setTorn(false);host.querySelector('.tear-ticket__piece--stub')?.focus({preventScroll:true})}}).catch(()=>{})}
function eventPage(e){const checked=attended(e),tap=location.pathname.startsWith('/tap/');app.innerHTML=`<a class="back" href="${e.source==='Ticketmaster'?'/artist/'+esc(e.artist_slug):'/'}"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>${e.source==='Ticketmaster'?'All '+esc(e.artist)+' dates':'All artists'}</a><section class="event-hero"><div class="event-ticket"><button type="button" class="ticket-reset" aria-label="Reset ticket" title="Reset ticket"><svg viewBox="0 0 24 24" aria-hidden="true"><g transform="matrix(-1 0 0 1 24 0)"><path class="ticket-reset-arc" d="M18.06 15.50A7 7 0 1 1 16.50 6.64"/><path class="ticket-reset-head" d="M19.40 9.07L13.83 8.51L17.88 3.68Z"/></g></svg></button><div class="event-ticket-host" data-event-ticket>${poster(e,true)}</div></div><div><p class="meta-line">${esc(e.city)} · ${e.source==='Ticketmaster'?'Ticketmaster listing':'Editable test event'}</p><h1>${esc(e.artist)}</h1><p class="event-detail">${esc(e.venue)}<br>${esc(e.date)}</p>${e.source==='Ticketmaster'?`<p class="muted">${esc(e.title)} · ${esc(e.status)}<br>Imported ${esc(e.imported_at)} · <a class="source-link" href="${esc(e.source_url)}" target="_blank" rel="noopener">View original listing</a></p>`:'<p class="muted">Artist, venue, date, and year are unconfirmed placeholders. No official affiliation.</p>'}${e.start_date&&e.start_date<=state.today?`<p><a class="button secondary" href="/log?event=${esc(e.id)}">Log this concert ${checked?'· already checked in':'without checking in'}</a></p>`:''}${checkinPanelMarkup(e,checked,tap)}</div></section><section class="community"><div class="section-head"><h2>Find your people.</h2>${checked?`<a class="checkin-tile" href="/profile" aria-label="Checked in to ${esc(e.artist)}. View your concert history."><span class="checkin-tile-glow" aria-hidden="true"></span>${STAR_SVG}<span class="checkin-tile-text"><strong>Checked in</strong><small>${esc(e.date)}</small></span></a>`:'<p class="community-open">Open to everyone. Check in to unlock the attendee chat.</p>'}</div><div class="tabs" role="tablist">${[['show','Show night'],['venue','Venue chat'],['chat','Attendee chat'],['photos','Photos']].map(([id,title])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''} ${id==='chat'&&checked?'chat-unlocked':''}">${esc(title)}${id==='chat'?(checked?`<span class="tab-star">${STAR_SVG}</span>`:LOCK_ICON):''}</button>`).join('')}</div><div id="discussion" class="${tab==='chat'&&checked?'exclusive-chat':''}"></div></section>`;mountEventTicket(e,checked);document.querySelector('#checkin').onclick=()=>{if(checked){location.href='/profile';return}if(tap&&state.demo_checkins_enabled!==false){autoCheckin(e);return}signed(()=>gpsCheckin(e))};const demoButton=document.querySelector('#simulate-nfc');if(demoButton)demoButton.onclick=()=>{location.href='/tap/'+e.id};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;eventPage(e)});mountCheckinTile();discussion(e)}
// The checked-in stub glows where the cursor is and tilts a little toward it.
function mountCheckinTile(){const tile=document.querySelector('.checkin-tile');if(!tile)return;const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 tile.addEventListener('pointermove',ev=>{const r=tile.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width,y=(ev.clientY-r.top)/r.height;tile.style.setProperty('--mx',(x*100).toFixed(1)+'%');tile.style.setProperty('--my',(y*100).toFixed(1)+'%');if(!still)tile.style.transform=`perspective(500px) rotateX(${((.5-y)*10).toFixed(2)}deg) rotateY(${((x-.5)*12).toFixed(2)}deg) translateY(-2px)`});
 tile.addEventListener('pointerleave',()=>{tile.style.transform='';tile.style.removeProperty('--mx');tile.style.removeProperty('--my')})}
function venueConnections(e){const linked=state.events.filter(other=>other.venue_key===e.venue_key&&(!other.source||other.source!=='Ticketmaster'||other.listed)).sort((a,b)=>(a.start_date||'9999').localeCompare(b.start_date||'9999'));return `<details class="venue-connections"><summary>${linked.length} show ${linked.length===1?'date shares':'dates share'} this venue chat</summary><p>Fans arriving through any of these shows join this same conversation.</p><div>${linked.map(other=>`<a href="/event/${esc(other.id)}">${esc(other.artist)} <span>${esc(other.date)}${other.id===e.id?' · This show':''}</span></a>`).join('')}</div></details>`}
const POST_TAGS=['Merch','BST','Box Office','Questions','Outfits','Views','Stories'];
const discussionFilters=new Map();let discussionRequest=0;
function matchesPostTag(post,tag){return tag==='all'||(post.tags||[]).includes(tag)}
function postMarkup(p){return `<article class="post"><div class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</div><div><a class="post-author" href="/profile/${esc(p.user)}"><strong>${esc(p.name)}</strong></a> ${p.attended?'<span class="badge"><svg class="icon-star icon-inline" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.6l2.75 5.95 6.5.72-4.86 4.4 1.38 6.4L12 16.8l-5.77 3.27 1.38-6.4-4.86-4.4 6.5-.72z"/></svg> Checked in</span>':''}<small>${new Date(p.created*1000).toLocaleString()}</small><p>${esc(p.body)}</p>${p.photo?`<img class="photo" src="${esc(p.photo)}" alt="Photo shared by ${esc(p.name)}">`:''}${p.tags?.length?`<div class="post-tag-labels">${p.tags.map(tag=>`<span class="post-tag">${esc(tag)}</span>`).join('')}</div>`:''}</div></article>`}
async function discussion(e){
 const request=++discussionRequest,box=document.querySelector('#discussion'),tagged=tab==='show'||tab==='chat';
 if(tab==='chat'&&!attended(e)){box.innerHTML=`<div class="empty"><span>${LOCK_ICON}</span><h3>A room for this show’s crowd.</h3><p>Check into ${esc(e.artist)} to unlock this event’s chat.<br>The public show-night and venue chats are open to everyone.</p><a class="button" href="/tap/${e.id}">Try this show’s demo NFC link</a></div>`;return}
 const scope=tab==='venue'?'venue:'+e.venue_key:tab==='chat'?'chat:'+e.id:'show:'+e.id;
 photo='';box.innerHTML='<p>Loading conversation…</p>';
 try{
  const [posts,feedPhotos]=await Promise.all([api('posts/'+encodeURI(scope)),tab==='photos'?api('event-feed/'+e.id):Promise.resolve([])]);if(request!==discussionRequest||!document.body.contains(box))return;
  let active=tagged?(discussionFilters.get(scope)||'all'):'all';
  const photoPosts=tab==='photos'?[...feedPhotos.map(p=>({...p,personalFeed:true,tags:[]})),...posts.filter(p=>p.photo)].sort((a,b)=>b.created-a.created):posts;
  box.innerHTML=`${tab==='chat'?'<div class="exclusive-welcome"><span class="chat-star">'+STAR_SVG+'</span><div><strong>You’re in. This is your crowd.</strong><p>A space for the people checked into this show.</p></div></div>':''}<div class="forum-head"><h3>${tab==='photos'?'The night, through your lens.':tab==='chat'?'Inside this night.':tab==='venue'?'Around '+esc(e.venue)+'.':'Before, during, and after the show.'}</h3><p>${tab==='chat'?'Only accounts checked into this event can read or post here.':tab==='photos'?'Photos from the crowd.':tab==='venue'?'One shared conversation for every show at this venue · no check-in required.':'Public discussion · no check-in required.'}</p><small>Attendance badges identify a check-in, not the accuracy of a post or photo.</small>${tab==='venue'?venueConnections(e):''}</div>${tagged?`<section class="topic-section" aria-label="Filter posts by tag"><div class="topic-filters">${[['all','All posts'],...POST_TAGS.map(tag=>[tag,tag])].map(([tag,label])=>`<button type="button" data-topic="${esc(tag)}" aria-pressed="${active===tag}"><span>${esc(label)}</span><small>${posts.filter(p=>matchesPostTag(p,tag)).length}</small></button>`).join('')}</div></section>`:''}${tab!=='photos'?'<section id="chat-threads" class="chat-threads"></section>':''}<p id="post-result-count" class="muted" role="status"></p><div class="posts ${tab==='photos'?'show-photo-gallery':''}" id="filtered-posts"></div>${tab==='photos'?`<div class="photo-post-callout"><h3>Make it part of your story.</h3><p>Post to your own feed and tag this show. Your photo will appear here too.</p><a class="button" href="/new-post?event=${esc(e.id)}"><svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>Post a photo to my feed</a></div>`:`<form id="postform"><label for="message">${tab==='photos'?'Share a photo and a caption':'Join the conversation'}</label><textarea id="message" required maxlength="2000" placeholder="What’s on your mind?"></textarea>${tagged?`<fieldset class="post-tags"><legend>Tag your post <span>(optional · choose more than one)</span></legend><div>${POST_TAGS.map(tag=>`<label class="tag-choice"><input type="checkbox" name="tags" value="${esc(tag)}" ${active===tag?'checked':''}><span>${esc(tag)}</span></label>`).join('')}</div></fieldset>`:''}<div class="compose-actions"><label class="file">${PLUS_SVG}Add photo<input type="file" id="photo" accept="image/jpeg,image/png,image/webp"></label><span id="photostatus"></span><button>${state.user?'Post':'Sign in to post'}</button></div><small>Posts are saved on this computer. Share only photos you have permission to use.</small></form>`}`;
  function drawPosts(){
   const display=photoPosts.filter(p=>matchesPostTag(p,active));
   document.querySelector('#post-result-count').textContent=tagged?`${display.length} ${display.length===1?'post':'posts'} · ${active==='all'?'All posts':active}`:'';
   document.querySelector('#filtered-posts').innerHTML=display.length?display.map(p=>p.personalFeed?feedPostMarkup(p):postMarkup(p)).join(''):`<div class="empty"><span>✦</span><h3>${tagged&&active!=='all'?`Start the ${esc(active)} conversation.`:tab==='photos'?'Every night has a point of view.':'You could start something.'}</h3><p>${tagged&&active!=='all'?`No posts tagged ${esc(active)} yet. Add that tag when sharing your post.`:tab==='photos'?'Share the first photo from this test show.':'Be the first to say hello. Try a meetup plan or a favorite song.'}</p></div>`;
   initializeCarousels(document.querySelector('#filtered-posts'));
   document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===active)));
  }
  if(tab!=='photos')mountThreads(scope,document.querySelector('#chat-threads'));
  drawPosts();
  document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{active=b.dataset.topic;discussionFilters.set(scope,active);drawPosts()});
  
  if(tab==='photos')return;
  document.querySelector('#photo').onchange=async ev=>{photo='';const f=ev.target.files[0];if(!f)return;if(f.size>RAW_PHOTO_LIMIT){toast('Choose a photo under 40 MB.');ev.target.value='';return}try{const clean=await cleanPhoto(f);if(clean.size>(state.max_photo_bytes||25000000))throw Error('Choose a smaller photo within the upload limit.');photo=clean.data}catch(err){toast(err.message);ev.target.value='';return}document.querySelector('#photostatus').textContent=f.name};
  document.querySelector('#postform').onsubmit=ev=>{ev.preventDefault();const body=document.querySelector('#message').value,selected=photo,category='general',tags=tagged?[...document.querySelectorAll('#postform input[name="tags"]:checked')].map(input=>input.value):[];if(tab==='photos'&&!selected){toast('Add a photo to share in Photos.');return}signed(async()=>{try{await api('post',{scope,body,photo:selected,category,tags});if(active!=='all'&&!tags.includes(active))discussionFilters.set(scope,'all');photo='';await discussion(e);toast('Posted.')}catch(err){toast(err.message)}})};
 }catch(err){if(request===discussionRequest)box.textContent=err.message}
}


function concertHistory(){return state.concert_history||state.attendance.map(a=>{const e=state.events.find(e=>e.id===a.event);return e?{...e,event_id:e.id,checked_in:true,created:a.created,points:a.points||100}:null}).filter(Boolean)}
