function ticketmasterOliviaShow(event){
 const date=event.start_date||event.date||'',city=performerKey(event.city||''),venue=performerKey(event.venue||'');
 const slug=event.artist_slug||artistList().find(person=>performerKey(person.artist)===performerKey(event.artist||''))?.artist_slug||'';
 if(slug!=='olivia-rodrigo'||!date||!city||!venue)return null;
 return oliviaSupportByNight.find(show=>show.dates.includes(date)&&[show.city,...(show.cityAliases||[])].some(name=>performerKey(name)===city)&&show.venues.some(name=>performerKey(name)===venue))||null;
}
