 const matched=ticketmasterOliviaShow(official||event);
 if(matched)return matched.artists.map(artist=>({artist,artist_slug:'',source_url:official?.source_url||ticketmasterOliviaUrl}));
 return explicit.map(item=>typeof item==='string'?{artist:item,source_url:event.source_url||''}:{artist:item.artist,artist_slug:item.artist_slug||'',source_url:item.source_url||event.source_url||''}).filter(item=>item.artist);
