 const explicit=[...(Array.isArray(event.performers)?event.performers:[]),...(Array.isArray(event.lineup)?event.lineup:[])];
 const lineup=[event,...explicit,...state.events.filter(sameShow),...historyEvents.filter(sameShow)],people=new Map();
 for(const item of lineup){const artist=typeof item==='string'?item:item.artist;if(!artist)continue;const slug=typeof item==='object'?(item.artist_slug||''):'';const key=performerKey(slug||artist);if(!people.has(key))people.set(key,{artist,artist_slug:slug})}
 return [...people.values()];
