 const optionsPeople=[...people,...suggestions.map(person=>({...person,suggestion:true})),...extraPeople.map(person=>({...person,addedByUser:true}))];
 const saved=event.id&&concertHistory().find(log=>log.event_id===event.id),savedKeys=new Set((saved?.artists_seen||[]).map(person=>performerKey(person.artist_slug||person.artist)));
