 paint();
 async function loadFriends(){if(friendsLoaded)return;friendsLoaded=true;if(!state.user){friendList.innerHTML='<p class="muted">Sign in to tag friends.</p>';return}try{const friends=(await api('people')).filter(person=>person.relationship==='friend');friendList.innerHTML=friends.length?friends.map(f=>`<button type="button" aria-pressed="${tagged.has(f.id)}" data-friend-id="${esc(f.id)}">${esc(f.name)}</button>`).join(''):'<p class="muted">No friends on Souvenue yet. <a href="/friends">Find friends</a> to tag them next time.</p>';friendList.querySelectorAll('[data-friend-id]').forEach(b=>b.onclick=()=>b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true')));friendsReady=true}catch(err){friendList.innerHTML=`<p class="muted">${esc(err.message)}</p>`}}
