 addBtn.onclick=()=>{if(validate())input.click()};
 if(skipBtn)skipBtn.onclick=()=>{if(!validate())return;photos=[];input.value='';preview.hidden=true;preview.innerHTML='';if(!saved?.photos?.length)backdropWrap.hidden=true;note.textContent='';addBtn.textContent='Add photos';openDetails()};
