 const showLogMode=manual=>{document.querySelector('#log-search').hidden=manual;document.querySelector('#log-manual').hidden=!manual;document.querySelector('#log-tab-search').setAttribute('aria-selected',String(!manual));document.querySelector('#log-tab-manual').setAttribute('aria-selected',String(manual));history.replaceState(null,'',manual?'/log?mode=manual':'/log'+(selected?'?artist='+encodeURIComponent(selected):''))};
