 document.querySelector('.log-choice').onkeydown=ev=>{if(['ArrowLeft','ArrowRight'].includes(ev.key)){ev.preventDefault();const toManual=!document.querySelector('#log-search').hidden;showLogMode(toManual);document.querySelector(toManual?'#log-tab-manual':'#log-tab-search').focus()}};
