function profile(){if(!state.user){app.innerHTML='<div class="empty"><h1>Collect the nights<br>you’ll never forget.</h1><p>Sign in to see your attendance badges and concert history.</p><button id="profilelogin">Sign in</button></div>';document.querySelector('#profilelogin').onclick=()=>signed(()=>load());return}app.innerHTML=`<h1>${esc(state.user.name)}’s nights.</h1><div class="profile-tabs" role="tablist" aria-label="Profile sections"><button type="button" role="tab" id="profile-overview-tab" aria-controls="profile-overview" aria-selected="true">My profile</button><button type="button" role="tab" id="profile-settings-tab" aria-controls="profile-settings" aria-selected="false">Settings</button></div><section id="profile-overview" role="tabpanel" aria-labelledby="profile-overview-tab"><div class="actions profile-actions"><a class="button" href="/new-post"><svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>New photo post</a><a class="button secondary" href="/log"><svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>Log a concert</a></div>${concertStatsMarkup()}<section class="personal-section"><h2>My photo feed.</h2><div id="my-feed" class="profile-feed-grid"></div></section><div class="section-head"><h2>Concert history.</h2></div><p class="muted">${concertHistory().length} ${concertHistory().length===1?'concert':'concerts'} logged · ${state.attendance.length} checked in</p><div class="concert-history-list">${historyMarkup()}</div><p class="muted">Attendance is recorded per account, once per event. Demo badges are not proof of physical presence.</p></section><section id="profile-settings" role="tabpanel" aria-labelledby="profile-settings-tab" hidden><h2>Settings.</h2><section class="leaderboard-preference"><div><h3>Leaderboard visibility</h3><p>Opt in to share your display name, concert count, and demo points publicly. Your photo privacy setting stays separate.</p></div><form id="leaderboard-preference"><label><input id="leaderboard-opt-in" type="checkbox" ${state.user.leaderboard_opt_in?'checked':''}> Show me on leaderboards</label><button>Save choice</button><p id="leaderboard-preference-status" role="status"></p></form></section><section class="privacy-settings"><div><h3>Choose your audience.</h3><p>Public: anyone can see your photo feed. Private: only you and accepted friends can see it, including photos tagged to shows.</p><small>Your name stays searchable. Messages and photos posted directly in discussions still follow that discussion’s access rules.</small></div><form id="privacy-form"><label for="profile-visibility">My profile is<select id="profile-visibility"><option value="public" ${state.user.visibility!=='private'?'selected':''}>Public</option><option value="private" ${state.user.visibility==='private'?'selected':''}>Private · friends only</option></select></label><button>Save privacy</button><p id="privacy-status" role="status"></p></form></section></section>`;const showProfileTab=settings=>{document.querySelector('#profile-overview').hidden=settings;document.querySelector('#profile-settings').hidden=!settings;document.querySelector('#profile-overview-tab').setAttribute('aria-selected',String(!settings));document.querySelector('#profile-settings-tab').setAttribute('aria-selected',String(settings))};document.querySelector('#profile-overview-tab').onclick=()=>{history.replaceState(null,'','/profile');showProfileTab(false)};document.querySelector('#profile-settings-tab').onclick=()=>{history.replaceState(null,'','/profile#settings');showProfileTab(true)};document.querySelector('.profile-tabs').onkeydown=ev=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const settings=ev.key==='End'||(ev.key!=='Home'&&document.querySelector('#profile-settings').hidden);document.querySelector(settings?'#profile-settings-tab':'#profile-overview-tab').click();document.querySelector(settings?'#profile-settings-tab':'#profile-overview-tab').focus()}};showProfileTab(location.hash==='#settings');bindLogDeletes();loadPersonalPosts(state.user.id,document.querySelector('#my-feed'));document.querySelector('#leaderboard-preference').onsubmit=async ev=>{ev.preventDefault();const enabled=document.querySelector('#leaderboard-opt-in').checked;try{await api('leaderboard-preference',{enabled});state.user.leaderboard_opt_in=enabled?1:0;document.querySelector('#leaderboard-preference-status').textContent=enabled?'Saved. Your name and score are visible on leaderboards.':'Saved. You are hidden from leaderboards.'}catch(err){document.querySelector('#leaderboard-preference-status').textContent=err.message}};document.querySelector('#privacy-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const result=await api('privacy',{visibility:document.querySelector('#profile-visibility').value});state.user.visibility=result.visibility;document.querySelector('#privacy-status').textContent=result.visibility==='private'?'Saved. Your feed is now visible only to you and accepted friends.':'Saved. Your feed is now public.'}catch(err){document.querySelector('#privacy-status').textContent=err.message}finally{button.disabled=false}}}
const LINK_ORDER=['Official site','Spotify','Apple Music','YouTube','SoundCloud','Instagram','TikTok','X','Facebook'];
function sortArtistLinks(links){const rank=l=>{const i=LINK_ORDER.indexOf(l.label);return i<0?LINK_ORDER.length:i};const hosts={X:['x.com','twitter.com']},ok=l=>{if(l.label==='Bandcamp')return false;const want=hosts[l.label];if(!want)return true;try{const h=new URL(l.url).hostname.toLowerCase();return want.some(d=>h===d||h.endsWith('.'+d))}catch{return false}};return links.filter(ok).sort((a,b)=>rank(a)-rank(b))}
function photoCarouselMarkup(p){const photos=p.photos?.length?p.photos:[p.photo];if(photos.length===1)return `${p.detail?'':`<a class="post-photo-link" href="/post/${esc(p.id)}" aria-label="Open photo post by ${esc(p.name)}">`}<img class="feed-image" src="${esc(photos[0])}" alt="${esc(p.body||'Concert photo shared by '+p.name)}" loading="lazy">${p.detail?'':'</a>'}`;return `<div class="photo-carousel" data-carousel role="region" aria-label="Photo carousel by ${esc(p.name)}"><div class="carousel-track" tabindex="0" aria-label="Swipe or use arrow keys to browse ${photos.length} photos">${photos.map((src,index)=>`<div class="carousel-slide">${p.detail?'':`<a class="post-photo-link" href="/post/${esc(p.id)}?photo=${index}" aria-label="Open photo ${index+1} in post by ${esc(p.name)}">`}<img class="feed-image" src="${esc(src)}" alt="Photo ${index+1} of ${photos.length}${p.body?': '+esc(p.body):''}" loading="lazy">${p.detail?'':'</a>'}</div>`).join('')}</div><span class="carousel-count" aria-live="polite">1 / ${photos.length}</span><button type="button" class="carousel-arrow carousel-previous" aria-label="Previous photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14.5 5.5 8 12l6.5 6.5"/></svg></button><button type="button" class="carousel-arrow carousel-next" aria-label="Next photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.5 5.5 16 12l-6.5 6.5"/></svg></button></div>`}
// Long captions and blurbs show 4 lines, then a "Show more" toggle.
function initClamps(root){for(const el of root.querySelectorAll?.('.clamp-4:not([data-clamped])')||[]){if(!el.clientHeight)continue;el.dataset.clamped='1';if(el.scrollHeight<=el.clientHeight+2)continue;const b=document.createElement('button');b.type='button';b.className='text-action clamp-toggle';b.textContent='Show more';b.setAttribute('aria-expanded','false');b.onclick=ev=>{ev.preventDefault();const open=el.classList.toggle('clamp-open');b.textContent=open?'Show less':'Show more';b.setAttribute('aria-expanded',String(open))};el.after(b)}}
// Run on anything rendered into #app (and when hidden tabs become visible).
{let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;initClamps(app)})}).observe(app,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden']})}
function initializeCarousels(root){initClamps(root);for(const carousel of root.querySelectorAll?.('[data-carousel]')||[]){const track=carousel.querySelector('.carousel-track'),slides=[...carousel.querySelectorAll('.carousel-slide')],dots=[...carousel.querySelectorAll('[data-slide]')],previous=carousel.querySelector('.carousel-previous'),next=carousel.querySelector('.carousel-next');let index=0;function update(){index=Math.max(0,Math.min(slides.length-1,Math.round(track.scrollLeft/(track.clientWidth||1))));carousel.querySelector('.carousel-count').textContent=(index+1)+' / '+slides.length;dots.forEach((dot,i)=>dot.setAttribute('aria-current',String(i===index)));previous.disabled=index===0;next.disabled=index===slides.length-1}function go(i){const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;track.scrollTo({left:Math.max(0,Math.min(slides.length-1,i))*track.clientWidth,behavior:reduced?'instant':'smooth'})}track.onscroll=update;previous.onclick=()=>go(index-1);next.onclick=()=>go(index+1);dots.forEach(dot=>dot.onclick=()=>go(Number(dot.dataset.slide)));track.onkeydown=ev=>{if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();go(index+(ev.key==='ArrowRight'?1:-1))}};update()}}

// ---- Polaroid frames --------------------------------------------------------
// state.backdrops comes from backdrops.json: plain colours, or patterned images
// in public/backdrops/. '' is the default white frame.
function frameOf(id){return (state.backdrops||[]).find(b=>b.id===id)||null}
function frameAttrs(id){const f=frameOf(id);if(!f)return '';return f.url?` data-frame="image" style="--frame:url('${esc(f.url)}')"`:` data-frame="${f.dark?'dark':'color'}" style="--frame-color:${esc(f.color)}"`}
function frameSwatchStyle(f){return f.url?`--swatch-img:url('${esc(f.url)}')`:`--swatch:${esc(f.color)}`}
function backdropPickerMarkup(selected=''){if(!state.backdrops?.length)return '';return `<fieldset class="backdrop-picker"><legend>Polaroid frame</legend><div class="backdrop-options"><button type="button" class="backdrop-swatch backdrop-white" data-backdrop="" aria-pressed="${!selected}" aria-label="White" title="White"></button>${state.backdrops.map(b=>`<button type="button" class="backdrop-swatch" data-backdrop="${esc(b.id)}" aria-pressed="${selected===b.id}" aria-label="${esc(b.name)}" title="${esc(b.name)}" style="${frameSwatchStyle(b)}"></button>`).join('')}</div></fieldset>`}
function bindBackdropPicker(root,onPick=()=>{}){const swatches=[...root.querySelectorAll('.backdrop-swatch')];let value=swatches.find(b=>b.getAttribute('aria-pressed')==='true')?.dataset.backdrop||'';swatches.forEach(b=>b.onclick=()=>{value=b.dataset.backdrop;swatches.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));onPick(value)});onPick(value);return ()=>value}
// Live preview: the photo thumbnails wear the picked frame.
function setBackdrop(el,id){const f=frameOf(id);el.style.removeProperty('--frame');el.style.removeProperty('--frame-color');if(!f){el.removeAttribute('data-frame');return}el.dataset.frame=f.url?'image':f.dark?'dark':'color';if(f.url)el.style.setProperty('--frame',`url("${f.url}")`);else el.style.setProperty('--frame-color',f.color)}
// A pink sequin star sticker with "Checked in!" when the poster checked into the tagged show.
function checkinStampMarkup(){return `<span class="checkin-stamp" role="img" aria-label="Checked in at this show"><img src="/stamps/checked-in-star.png" alt="" width="240" height="236"><span class="checkin-stamp-text" aria-hidden="true">Checked<br>in!</span></span>`}
function feedPostMarkup(p){const day=/^\d{4}-\d\d-\d\d$/.test(p.date||'')?new Date(p.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):p.date||'',show=p.artist?`<strong>${esc(p.artist)}</strong><small>${esc([p.venue,p.city].filter(Boolean).join(' · '))}${day?' · '+esc(day):''}</small>`:'';
 // The whole post lives inside the polaroid; its border is white, a colour, or a pattern the poster picked.
 return `<article class="feed-post polaroid-post" id="photo-post-${esc(p.id)}"><div class="polaroid"${frameAttrs(p.backdrop)}><div class="feed-post-head"><a class="feed-author" href="/profile/${esc(p.user)}"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><strong>${esc(p.name)}</strong></a><span class="feed-post-date">${new Date(p.created*1000).toLocaleDateString()}</span></div>${photoCarouselMarkup(p)}<div class="polaroid-strip">${p.attended?checkinStampMarkup():''}${p.body?(p.detail?`<p class="polaroid-caption clamp-4">${esc(p.body)}</p>`:`<a class="polaroid-caption post-caption-link clamp-4" href="/post/${esc(p.id)}">${esc(p.body)}</a>`):''}${show?(p.event_id?`<a class="polaroid-show" href="/event/${esc(p.event_id)}">${show}</a>`:`<div class="polaroid-show">${show}</div>`):''}${p.detail?'':`<a class="open-photo-post" href="/post/${esc(p.id)}">View post</a>`}</div></div></article>`}
async function photoPostPage(pid){app.innerHTML='<p>Opening photo post…</p>';try{const post=await api('photo-post/'+pid);if(location.pathname!=='/post/'+pid)return;app.innerHTML=`<a class="back" href="/profile/${esc(post.user)}"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>${esc(post.name)}’s profile</a><section class="single-photo-post">${feedPostMarkup({...post,detail:true})}</section>${state.user?.id===post.user?`<label class="feature-optin"><input type="checkbox" id="post-featured" ${post.featured?'checked':''}><span>Feature this photo on the Souvenue home page<small>Only shown while your profile is public.</small></span></label>`:''}<a class="back" href="/feed"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>Explore the photo feed</a>`;initializeCarousels(app);const featureBox=document.querySelector('#post-featured');if(featureBox)featureBox.onchange=async()=>{featureBox.disabled=true;try{await api('feed-post-feature',{id:pid,featured:featureBox.checked});toast(featureBox.checked?'Your photo can now be featured on the home page.':'Your photo won’t be featured.')}catch(err){featureBox.checked=!featureBox.checked;toast(err.message)}featureBox.disabled=false};const track=document.querySelector('.single-photo-post .carousel-track');if(track){const selected=Math.max(0,Math.min((post.photos?.length||1)-1,Number(new URLSearchParams(location.search).get('photo'))||0));track.scrollTo({left:selected*track.clientWidth,behavior:'instant'})}}catch(err){app.innerHTML=`<a class="back" href="/feed"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>Photo feed</a><div class="empty"><h1>Post unavailable.</h1><p>${esc(err.message)}</p></div>`}}

async function loadPersonalPosts(uid,container){container.innerHTML='<p class="muted">Loading photos…</p>';try{const posts=await api('feed/'+uid);if(!document.body.contains(container))return;container.innerHTML=posts.length?posts.map(feedPostMarkup).join(''):'<div class="empty"><h3>A fresh roll of memories.</h3><p>No personal photo posts yet.</p></div>';initializeCarousels(container)}catch(err){container.textContent=err.message}}
