function profileFriendActions(person){const r=person.relationship,b=(action,label,cls='')=>`<button${cls?` class="${cls}"`:''} data-profile-friend="${action}">${label}</button>`;
 return `<div class="person-actions profile-friend-actions">${r==='friend'?`<span class="friend-status">✓ Friends</span>${b('remove','Remove friend','text-action')}`:r==='received'?`<span class="friend-status">${esc(person.name)} wants to be friends</span>${b('accept','Accept')}${b('decline','Decline','secondary')}`:r==='sent'?b('cancel','Cancel request','secondary'):b('request','<svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>Add friend')}</div>`}
