async function personalProfile(uid){app.innerHTML='<p>Loading profile…</p>';try{const person=await api('profile/'+uid);if(location.pathname!=='/profile/'+uid)return;app.innerHTML=`<a class="back" href="/feed"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>Community feed</a><h1>${esc(person.name)}’s feed.</h1>${person.username?`<p class="meta-line profile-handle">@${esc(person.username)}</p>`:''}<p class="muted">Photos and stories shared by ${esc(person.name)}.</p>${state.user?.id===uid?'<a class="button" href="/new-post"><svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>New photo post</a>':profileFriendActions(person)}<section class="personal-section"><div id="member-feed" class="profile-feed-grid"></div></section>`;if(!person.can_view){document.querySelector('#member-feed').innerHTML=`<div class="private-profile"><h2>This profile is private.</h2><p>Only accepted friends can see ${esc(person.name)}’s photos.</p></div>`}else await loadPersonalPosts(uid,document.querySelector('#member-feed'));bindProfileFriendActions(uid)}catch(err){app.textContent=err.message}}
async function feedPage(){app.innerHTML=`<section class="feed-page-head"><div><h1>The night, shared.</h1><p>Personal photo posts from the community. Tag a show and keep the memory connected.</p></div><a class="button" href="/new-post"><svg class="icon-plus" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>New photo post</a></section><div id="community-feed" class="community-photo-feed"></div>`;const container=document.querySelector('#community-feed');container.innerHTML='<p>Loading photos…</p>';try{const posts=await api('feed');if(!document.body.contains(container))return;container.innerHTML=posts.length?posts.map(feedPostMarkup).join(''):'<div class="empty"><span>✦</span><h2>Someone has to post the first night.</h2><p>Share a photo on your own feed, with an optional show tag.</p><a class="button" href="/new-post">Create the first post</a></div>';initializeCarousels(container)}catch(err){container.textContent=err.message}}
function newFeedPost(){
 const prefill=new URLSearchParams(location.search).get('event')||'';let selectedPhotos=[],readingPhotos=false;
 const events=state.events.filter(e=>e.source!=='Ticketmaster'||e.listed).sort((a,b)=>(b.start_date||'').localeCompare(a.start_date||'')||a.artist.localeCompare(b.artist));
 app.innerHTML=`<a class="back" href="/feed"><svg class="icon-back" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3.5M7.5 3.5 3 8l4.5 4.5"/></svg>Community feed</a><section class="create-photo"><h1>Post the feeling.</h1><p class="muted">Your post lives on your profile. Its visibility follows your Public / Private setting, including when it’s tagged to a show.</p><form id="feedform"><label class="photo-upload">Choose photos<input id="feed-photo" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>Up to 10 photos · ${Math.floor((state.max_photo_bytes||25000000)/1000000)} MB each · ${((state.max_post_photo_bytes||100000000)/1000000).toFixed(1)} MB total</small></label><div id="feed-preview" class="selected-photo-preview" hidden></div><div id="feed-backdrop">${backdropPickerMarkup()}</div><label>Caption<textarea id="feed-caption" maxlength="2000" placeholder="The song. The outfit. The view from your seat…"></textarea></label><fieldset class="event-picker"><legend>Tag a show <span>(optional)</span></legend><label for="feed-event-search">Find an artist, venue, or city<input name="feed-event-search" autocomplete="off" id="feed-event-search" type="search" placeholder="Search for your night…"></label><label for="feed-event">Show<select id="feed-event"></select></label><div id="feed-event-label" class="muted"></div></fieldset><p class="muted">Tagging a show doesn’t record attendance or unlock its chat. A badge appears only if you’ve checked into that exact show.</p><label class="feature-optin"><input type="checkbox" id="feed-featured"><span>Feature this photo on the Souvenue home page<small>Only shown while your profile is public. You can turn this off on the post anytime.</small></span></label><p id="feed-error" role="alert"></p><button id="publish-photo">${state.user?'Post to my feed':'Sign in to post'}</button><small>Your Public / Private profile setting controls who can see this photo. Share photos you have permission to use.</small></form></section>`;
 const selector=document.querySelector('#feed-event');let selectedEvent=events.some(e=>e.id===prefill)?prefill:'';
 function fillEvents(){const query=normalizeSearch(document.querySelector('#feed-event-search').value);const matches=events.filter(e=>normalizeSearch([e.artist,e.venue,e.city,e.date].join(' ')).includes(query));const chosen=events.find(e=>e.id===selectedEvent);const options=chosen&&!matches.includes(chosen)?[chosen,...matches]:matches;selector.innerHTML='<option value="">No show tag</option>'+options.map(e=>`<option value="${esc(e.id)}">${esc(e.artist)} · ${esc(e.date)} · ${esc(e.city)} · ${esc(e.venue)}${e.source==='Demo'?' [TEST EVENT]':''}</option>`).join('');selector.value=selectedEvent;document.querySelector('#feed-event-label').textContent=query?matches.length+' matching shows':''}
 fillEvents();document.querySelector('#feed-event-search').oninput=fillEvents;selector.onchange=()=>{selectedEvent=selector.value};
 const feedBackdrop=bindBackdropPicker(document.querySelector('#feed-backdrop'),id=>setBackdrop(document.querySelector('#feed-preview'),id));
 function drawPreview(){const preview=document.querySelector('#feed-preview');preview.hidden=!selectedPhotos.length;preview.innerHTML=`<p class="muted">${selectedPhotos.length} / 10 photos · choose more to add to your carousel</p><div class="selected-photo-grid">${selectedPhotos.map((image,i)=>`<div class="selected-photo"><img src="${esc(image.data)}" alt="Selected photo ${i+1}"><span>${i+1}</span><div><button type="button" data-photo-left="${i}" ${i===0?'disabled':''} aria-label="Move photo ${i+1} earlier"><svg class="icon-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg></button><button type="button" data-photo-right="${i}" ${i===selectedPhotos.length-1?'disabled':''} aria-label="Move photo ${i+1} later"><svg class="icon-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg></button><button type="button" data-photo-remove="${i}" aria-label="Remove photo ${i+1}">×</button></div></div>`).join('')}</div>`;document.querySelectorAll('[data-photo-remove]').forEach(b=>b.onclick=()=>{selectedPhotos.splice(Number(b.dataset.photoRemove),1);drawPreview()});for(const direction of ['left','right'])document.querySelectorAll('[data-photo-'+direction+']').forEach(b=>b.onclick=()=>{const i=Number(b.dataset[direction==='left'?'photoLeft':'photoRight']),other=i+(direction==='left'?-1:1);[selectedPhotos[i],selectedPhotos[other]]=[selectedPhotos[other],selectedPhotos[i]];drawPreview()})}
 document.querySelector('#feed-photo').onchange=async ev=>{const input=ev.target,error=document.querySelector('#feed-error');const files=[...input.files].filter(file=>!selectedPhotos.some(image=>image.key===[file.name,file.size,file.lastModified].join(':')));error.textContent='';if(!files.length)return;if(selectedPhotos.length+files.length>10){error.textContent='Choose up to 10 photos per post.';input.value='';return}if(files.some(file=>file.size>RAW_PHOTO_LIMIT||!['image/jpeg','image/png','image/webp'].includes(file.type))){error.textContent='Choose JPEG, PNG or WebP photos under 40 MB each.';input.value='';return}readingPhotos=true;input.disabled=true;document.querySelector('#publish-photo').disabled=true;try{const added=[];for(const file of files){const {data,size}=await cleanPhoto(file);if(size>(state.max_photo_bytes||25000000))throw Error('One of these photos is still too large. Please choose another.');added.push({data,size,key:[file.name,file.size,file.lastModified].join(':')})}if(selectedPhotos.reduce((total,image)=>total+image.size,0)+added.reduce((total,image)=>total+image.size,0)>(state.max_post_photo_bytes||100000000))throw Error('These photos are too large together. Remove one and try again.');selectedPhotos.push(...added);drawPreview()}catch(err){error.textContent=err.message}finally{readingPhotos=false;input.disabled=false;input.value='';document.querySelector('#publish-photo').disabled=false}};
 document.querySelector('#feedform').onsubmit=ev=>{ev.preventDefault();const error=document.querySelector('#feed-error');error.textContent='';if(readingPhotos||!selectedPhotos.length){error.textContent='Choose photos and wait for their previews to load.';return}const payload={body:document.querySelector('#feed-caption').value,photos:selectedPhotos.map(image=>image.data),event_id:selectedEvent||null,featured:document.querySelector('#feed-featured').checked,backdrop:feedBackdrop()};signed(async()=>{const button=document.querySelector('#publish-photo');button.disabled=true;button.textContent='Posting…';try{await api('feed-post',payload);location.href='/profile'}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Post to my feed'}})};
}

